pub fn solve_rival_distance(n: i8, x: i8, a: i8, b: i8) -> i8 {
    // Initial separation
    let initial_dist = (a - b).abs();
    // Add up to x moves without ever panicking on overflow
    let max_possible = initial_dist.saturating_add(x);
    // The largest separation on an [1..n] line is n-1
    let max_separation = n - 1;
    // Clamp down if we exceeded n-1
    std::cmp::min(max_possible, max_separation)
}

