    #[test]
    fn basic_examples() {
        // initial distance = 4, +3 moves = 7, but max on length 10 is 9
        assert_eq!(solve_rival_distance(10, 3, 2, 6), 7);
        // initial distance = 4, +10 moves = 14 => clamp to 9
        assert_eq!(solve_rival_distance(10, 10, 2, 6), 9);
        // reversed a/b order doesn't matter
        assert_eq!(solve_rival_distance(10, 3, 6, 2), 7);
    }

    #[test]
    fn edge_cases() {
        // Already at max separation
        assert_eq!(solve_rival_distance(5, 100, 1, 5), 4);
        // zero moves
        assert_eq!(solve_rival_distance(5, 0, 2, 4), 2);
        // minimal size
        assert_eq!(solve_rival_distance(2, 100, 1, 2), 1);
    }
